import itertools, random
from swarmgrid.model import Map, Mission, Closure
from swarmgrid.solver import plan_mission, position_at, ClosureTable

def brute(map_rec, agents, table, horizon=10):
    all_paths = []
    for agent in agents:
        single = []
        stack = [(agent.start, (agent.start,))]
        while stack:
            cell, path = stack.pop()
            t = len(path)-1
            if table.blocks(cell, t):
                continue
            if t > horizon:
                continue
            if cell == agent.goal:
                single.append(path); continue
            for nb in map_rec.neighbors(cell):
                if not table.blocks(nb, t+1):
                    stack.append((nb, path+(nb,)))
            if not table.blocks(cell, t+1):
                stack.append((cell, path+(cell,)))
        all_paths.append(single)
    def ok(combo):
        goals={p[-1] for p in combo}
        if len(goals)!=len(combo): return False
        H=max(len(p) for p in combo)
        for t in range(H):
            here=[position_at(p,t) for p in combo]
            live=[c for c in here if c is not None]
            if len(set(live))!=len(live): return False
            nxt=[position_at(p,t+1) for p in combo]
            for i in range(len(combo)):
                for j in range(i+1,len(combo)):
                    if here[i] and here[j] and nxt[i] and nxt[j] and nxt[i]==here[j] and nxt[j]==here[i]:
                        return False
        return True
    for combo in itertools.product(*all_paths):
        if ok(combo): return combo
    return None

rng=random.Random(99)
false_neg=false_pos=checked=0
for trial in range(300):
    w=rng.randint(2,4); h=rng.randint(2,4)
    rows=["".join("#" if rng.random()<0.2 else "." for _ in range(w)) for _ in range(h)]
    free=[(x,y) for y in range(h) for x in range(w) if rows[y][x]=="."]
    if len(free)<4: continue
    m=Map.parse({"id":"m","width":w,"height":h,"grid":rows})
    n=rng.randint(1,2)
    starts=rng.sample(free,n)
    agents=[]
    used=set(starts)
    for s in starts:
        cands=[c for c in free if c not in used]
        if not cands: break
        g=rng.choice(cands); used.add(g)
        agents.append({"id":f"a{len(agents)}","start":list(s),"goal":list(g)})
    if len(agents)!=n: continue
    # random closures: 1-3 intervals, 1-3 walkable cells each, ticks within 0..8
    clos=[]
    for _ in range(rng.randint(1,3)):
        cells=[list(c) for c in rng.sample(free, rng.randint(1,min(3,len(free))))]
        a0=rng.randint(0,6); a1=rng.randint(a0,8)
        clos.append(Closure(tuple(tuple(c) for c in cells),a0,a1))
    try:
        mis=Mission.parse({"id":"x","map_id":"m","agents":agents},m)
    except Exception:
        continue
    # skip sealed-start cases (prechecked, by design unsolvable)
    table=ClosureTable(clos)
    res=plan_mission(m,mis,tree_budget=4096,closures=clos)
    witness=brute(m,tuple(sorted(mis.agents,key=lambda a:a.id)),table)
    checked+=1
    if res.status=="solved":
        # verify plan honors closures
        for path in res.paths:
            for t,cell in enumerate(path):
                assert not table.blocks(cell,t),(trial,t,cell)
        if witness is None:
            false_pos+=1; print("FALSE SOLVED?", trial)
    else:
        if witness is not None:
            false_neg+=1
            print("FALSE UNSOLVABLE trial",trial,rows,agents,[(c.cells,c.start_tick,c.end_tick) for c in clos])
print(f"checked={checked} false_neg={false_neg} false_pos={false_pos}")
EOF

